","originalContent":""""
Fastapi using this file as association with app to run.
Actual app defined in auth54/__init__.py to avoid
possible circular imports.
"""

import sys

sys.path.append("..")
import uvicorn

from service54 import app
from service54.core.exceptions import Auth54SettingsError
from service54.settings import (
    AUTH_PUB_KEY,
    DATABASE,
    DEFAULT_GROUP_NAME,
    PRIMARY_KEY_ONLY,
    SECRET_KEY,
    SERVICE_PRIVATE_KEY,
)

# Check that all required settings are set up.
if not SECRET_KEY:
    raise Auth54SettingsError("Please set SECRET_KEY settings in local_settings.py")

if not AUTH_PUB_KEY:
    raise Auth54SettingsError("Please set AUTH_PUB_KEY settings in local_settings.py")

if not DATABASE["NAME"]:
    raise Auth54SettingsError("Please set DATABASE setting in local_settings.py")

if not DEFAULT_GROUP_NAME:
    raise Auth54SettingsError("Please set DEFAULT_GROUP settings in local_settings.py")

if PRIMARY_KEY_ONLY is None:
    raise Auth54SettingsError(
        "Please set PRIMARY_KEY_ONLY settings in local_settings.py"
    )

if not SERVICE_PRIVATE_KEY:
    raise Auth54SettingsError(
        "Please set SERVICE_PRIVATE_KEY settings in local_settings.py"
    )

# if not SERVICE_UUID:
#     raise Auth54SettingsError(
#         'Please set SERVICE_UUID settings in local_settings.py')

if __name__ == "__main__":
    uvicorn.run(app)
